import java.io.*;
import java.util.*;

import org.apache.commons.csv.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String data = "judul,id\nBelajar CSV,1\n";
        CSVFormat format = CSVFormat.DEFAULT.builder()
                .setHeader()
                .setSkipHeaderRecord(true)
                .build();
        for (CSVRecord r : CSVParser.parse(data, format)) {
            System.out.println("get(0) = " + r.get(0));
            System.out.println("get(\"id\") = " + r.get("id"));
        }
    }
}

