import java.io.*;
import java.util.*;

import org.apache.commons.csv.*;

public class Main {
    public static void main(String[] args) throws IOException {
        CSVFormat format = CSVFormat.DEFAULT.builder()
                .setDelimiter(';')
                .setHeader()
                .setSkipHeaderRecord(true)
                .build();
        for (CSVRecord r : format.parse(new InputStreamReader(System.in))) {
            int nilai = Integer.parseInt(r.get("stok")) * Integer.parseInt(r.get("harga"));
            System.out.println(r.get("nama") + ": " + nilai);
        }
    }
}
